import { Navigate, Outlet } from "react-router-dom";
import { useAuth } from "./utils/auth"; // Adjust path based on your structure

const PublicRoute = () => {
  const { user } = useAuth();

  return user ? <Navigate to="/home" replace /> : <Outlet />;
};

export default PublicRoute;
